  return {
  buf = buf, 
  win = win, 
  row = start.line, 
  col = start.character, 
  line = line, 
  word = line and vim.fn.expand("<cword>"), 
  ts_type = node and node:type(), 
  ts_range = node and {node:range()}, 
  bufname = file, 
  root = vim.fs.root(file, {".git", ".gitignore"}) or "", 
  filetype = vim.api.nvim_get_option_value("filetype", {buf = buf}), 
